static fm_result_t telemetry_cleanup_handler(const fm_fast_file_info_t *const gfi, void *const user_data)
{
    UNUSED(user_data);
    char fullname[FM_MAX_PATH];
    if ('\0' == gfi->p_path[0])
    {
        fm_delete(gfi->p_name);
    }
    else
    {
        (void)memset(fullname, 0U, sizeof(fullname));
        snprintf(fullname, sizeof(fullname), "%s/%s", gfi->p_path, gfi->p_name);
        fm_delete(fullname);
    }
    return FM_RES_OK;
}

