/** @brief Checks if the telemetry instance directory exists and if not - creates it.
 *
 *  @param[in] p_tlm_filesink_rt_ctx telemetry file sink runtime context
 */
static void telemetry_file_sink_check_create_tlm_dir(tlm_file_sink_rt_ctx_t *const p_tlm_filesink_rt_ctx)
{
    CRIT_ASSERT(NULL != p_tlm_filesink_rt_ctx);

    if ('\0' == p_tlm_filesink_rt_ctx->current_folder_name[0])
    {
        (void)snprintf(p_tlm_filesink_rt_ctx->current_folder_name, TLM_DIR_MAX_NAME_SIZE, "/sd/tlm_%u", (uint16_t)p_tlm_filesink_rt_ctx->sm_instance_id);
    }

    fm_dir_obj_t dir_obj = { 0 };

    // check if directory exists...
    if (FM_RES_OK == fm_dir_open(&dir_obj, p_tlm_filesink_rt_ctx->current_folder_name, NULL))
    {
        fm_dir_close(&dir_obj);
    }
    else
    {
        // directory doesn't exist, so it must be created
        fm_result_t mkdir_res = fm_mkdir(p_tlm_filesink_rt_ctx->current_folder_name);

        if (FM_RES_OK == mkdir_res)
        {
            ES_TRACE_DEBUG("[%u] new folder '%s' created", p_tlm_filesink_rt_ctx->sm_instance_id, p_tlm_filesink_rt_ctx->current_folder_name);
        }
        else
        {
            ES_TRACE_ERROR("[%u] could not create tlm folder '%s'. failed with error '%s'.",
                           p_tlm_filesink_rt_ctx->sm_instance_id,
                           p_tlm_filesink_rt_ctx->current_folder_name,
                           fm_result_to_str(mkdir_res));
        }
    }
}

