// Action handlers
// GEN_OBJ_START::telemetry_file_sink_sm_action_reload_config
void telemetry_file_sink_sm_action_reload_config(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_reload_config
    tlm_file_sink_rt_ctx_t *const p_tlm_filesink_rt_ctx = &telemetry_cfg_get_ctx_u16(instance_id)->tlm_file_sink_rt;

    telemetry_cfg_get_file_config((TELEMETRY_TelemetryInstance_t)instance_id, &p_tlm_filesink_rt_ctx->cfg);
    bool cfg_changed = (p_tlm_filesink_rt_ctx->prev_cfg.cfg_type != p_tlm_filesink_rt_ctx->cfg.cfg_type) ||
                       (p_tlm_filesink_rt_ctx->prev_cfg.params.u16Max_log_files_cnt != p_tlm_filesink_rt_ctx->cfg.params.u16Max_log_files_cnt) ||
                       (p_tlm_filesink_rt_ctx->prev_cfg.params.u32Size_limit_kb != p_tlm_filesink_rt_ctx->cfg.params.u32Size_limit_kb);

    if (true == cfg_changed)
    {
        p_tlm_filesink_rt_ctx->prev_cfg = p_tlm_filesink_rt_ctx->cfg;

        ES_TRACE_INFO("[%u] telemetry file configuration change detected", instance_id);

        BREAK_ASSERT(TELEMETRY_TLM_FILE_LOGGING_TYPE_SIZE_LIMIT == p_tlm_filesink_rt_ctx->cfg.cfg_type);
        BREAK_ASSERT(0U != p_tlm_filesink_rt_ctx->cfg.params.u16Max_log_files_cnt);
        BREAK_ASSERT(0U != p_tlm_filesink_rt_ctx->cfg.params.u32Size_limit_kb);

        if ((0U != p_tlm_filesink_rt_ctx->cfg.params.u16Max_log_files_cnt) &&
            (0U != p_tlm_filesink_rt_ctx->cfg.params.u32Size_limit_kb))
        {
            p_tlm_filesink_rt_ctx->max_file_size_bytes =
                (p_tlm_filesink_rt_ctx->cfg.params.u32Size_limit_kb * 1024U) / p_tlm_filesink_rt_ctx->cfg.params.u16Max_log_files_cnt;
        }
        else
        {
            p_tlm_filesink_rt_ctx->max_file_size_bytes = DEFAULT_FILE_SZ_IF_CFG_INVALID_KB;
        }
    }

    // restore operational persistent data from NVM
    telemetry_cfg_get_persistent_data(p_tlm_filesink_rt_ctx->sm_instance_id, &p_tlm_filesink_rt_ctx->persistent_data);
    // USER_CODE_END::action_reload_config
}
// GEN_OBJ_END::telemetry_file_sink_sm_action_reload_config

// GEN_OBJ_START::telemetry_file_sink_sm_action_prepare_file_telemetry
void telemetry_file_sink_sm_action_prepare_file_telemetry(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_prepare_file_telemetry
    tlm_file_sink_rt_ctx_t *const p_tlm_filesink_rt_ctx = &telemetry_cfg_get_ctx_u16(instance_id)->tlm_file_sink_rt;

    // reload configuration explicitly, just in case we couldn't load it in one of the previous states
    telemetry_file_sink_sm_action_reload_config(instance_id, pSMRoot, pEvent);

    CRIT_ASSERT(NULL != p_tlm_filesink_rt_ctx);
    CRIT_ASSERT(p_tlm_filesink_rt_ctx->max_file_size_bytes >= TLM_MSG_SIZE_BYTES_LEAST);

    // if last stored index is out of bounds, reset it
    if (p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx >= p_tlm_filesink_rt_ctx->cfg.params.u16Max_log_files_cnt)
    {
        ES_TRACE_WARN("[%u:%u] pd idx force reset", p_tlm_filesink_rt_ctx->sm_instance_id, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx);

        telemetry_upd_file_idx(p_tlm_filesink_rt_ctx, 0);
    }

    telemetry_file_sink_prepare_file_access(p_tlm_filesink_rt_ctx);
    ES_TRACE_DEBUG("[%u:%u] preparing '%s' for update", p_tlm_filesink_rt_ctx->sm_instance_id, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx, p_tlm_filesink_rt_ctx->current_file_name);
    // USER_CODE_END::action_prepare_file_telemetry
}
// GEN_OBJ_END::telemetry_file_sink_sm_action_prepare_file_telemetry

// GEN_OBJ_START::telemetry_file_sink_sm_action_store_telemetry
void telemetry_file_sink_sm_action_store_telemetry(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_store_telemetry
    fm_result_t                   res;
    fm_file_obj_t                 tlm_file_handle;
    tlm_file_hdr_t                fhdr;
    tlm_file_sink_rt_ctx_t *const p_tlm_filesink_rt_ctx = &telemetry_cfg_get_ctx_u16(instance_id)->tlm_file_sink_rt;
    tlm_queue_rt_t *const         p_tlm_queue_rt        = &telemetry_cfg_get_ctx_u16(instance_id)->tlm_queue;

    telemetry_queue_update_stats(p_tlm_queue_rt, TLM_STATS_ID_ACTIVE_SLOT, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx);

    (void)memset(&fhdr, 0U, sizeof(fhdr));
    res = fm_open(&tlm_file_handle,
                  p_tlm_filesink_rt_ctx->current_file_name,
                  (uint32_t)(FM_MODE_OPEN_ALWAYS | FM_MODE_READ | FM_MODE_WRITE));

    if (FM_RES_OK == res)
    {
        verify_tlm_header(&tlm_file_handle, &fhdr);

        uint16_t next_msg_size   = telemetry_queue_peek(p_tlm_queue_rt);
        uint64_t free_bytes      = telemetry_file_sink_getfreebytes(p_tlm_filesink_rt_ctx);
        uint32_t batch_msg_count = 0U;

        if (free_bytes > (uint64_t)next_msg_size)
        {
            bool continue_op = true;

            while ((next_msg_size > 0U) && (true == continue_op))
            {
                uint32_t bytes_written = 0U;

                if (true == telemetry_file_sink_shall_write(p_tlm_filesink_rt_ctx, fhdr.next_write_offset, next_msg_size))
                {
                    uint16_t bytes_read_from_queue = telemetry_queue_pop(p_tlm_queue_rt, p_tlm_filesink_rt_ctx->tlm_msg_buffer,
                                                                         sizeof(p_tlm_filesink_rt_ctx->tlm_msg_buffer));

                    CRIT_ASSERT(bytes_read_from_queue == next_msg_size);

                    res = fm_write(&tlm_file_handle,
                                   p_tlm_filesink_rt_ctx->tlm_msg_buffer,
                                   bytes_read_from_queue,
                                   &bytes_written);

                    uint32_t file_size = 0;
                    (void)fm_tell(&tlm_file_handle, &file_size);
                    fhdr.next_write_offset = file_size;

                    if ((FM_RES_OK != res) || (bytes_written != bytes_read_from_queue))
                    {
                        ES_TRACE_ERROR("[%u:%u] tlm write error [%d]", instance_id, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx, res);

                        // exit the loop (not using break due to SonarQube complaints)
                        continue_op = false;
                    }
                    else
                    {
                        fhdr.file_complete = false;

                        telemetry_file_sink_write_hdr(&tlm_file_handle, &fhdr);

                        next_msg_size = telemetry_queue_peek(p_tlm_queue_rt);

                        batch_msg_count++;

                        ES_TRACE_DEBUG("[%u:%u] tlm wrt @ offs %lu", instance_id, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx, fhdr.next_write_offset);
                    }
                }
                else
                {
                    ES_TRACE_DEBUG("[%u:%u] no space in current file. switching to next slot...", instance_id, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx);

                    fhdr.reserved      = 0U;
                    fhdr.file_complete = true;
                    // next writes in this file will start from
                    fhdr.next_write_offset = sizeof(tlm_file_hdr_t);

                    // Note: Order is important here in case of intermediate reset after this point! The next file slot must be
                    // prepared first before marking the current one as complete, otherwise we may end up with the current file complete and
                    // no partial slot to continue from next time after reset.
                    telemetry_file_sink_prepare_next_slot(p_tlm_filesink_rt_ctx);

                    // call this after telemetry_file_sink_prepare_next_slot() to ensure correct recovery in case of CPU reset between these
                    // two calls
                    telemetry_file_sink_write_hdr(&tlm_file_handle, &fhdr);

                    // exit the loop (not using break due to SonarQube complaints)
                    continue_op = false;
                }
            }

            // report statistics on last run...
            telemetry_queue_update_stats(p_tlm_queue_rt, TLM_STATS_ID_BATCH_COUNT, batch_msg_count);
        }
        else
        {
            ES_TRACE_WARN("no space left on storage. %" PRIu64 " free bytes remaining.", free_bytes);
        }

        (void)fm_close(&tlm_file_handle);
    }
    else
    {
        ES_TRACE_WARN("[%u:%u] unexpected result [%d] when opening file. skipping this slot.", instance_id, p_tlm_filesink_rt_ctx->persistent_data.last_file_slot_idx, res);
        telemetry_file_sink_prepare_next_slot(p_tlm_filesink_rt_ctx);
    }

    // USER_CODE_END::action_store_telemetry
}
// GEN_OBJ_END::telemetry_file_sink_sm_action_store_telemetry

// GEN_OBJ_START::telemetry_file_sink_sm_action_clean_and_reload_cfg
void telemetry_file_sink_sm_action_clean_and_reload_cfg(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_clean_and_reload_cfg
    tlm_runtime_context_t *p_tlm_rt_ctx = telemetry_cfg_get_ctx_u16(instance_id);

    telemetry_file_sink_sm_action_reload_config(instance_id, pSMRoot, pEvent);

    telemetry_file_sink_clean(&p_tlm_rt_ctx->tlm_file_sink_rt);
    // USER_CODE_END::action_clean_and_reload_cfg
}
// GEN_OBJ_END::telemetry_file_sink_sm_action_clean_and_reload_cfg
